define(['jquery','mage/translate','mage/template'],function($,$t,templateRenderer){$.widget('ambase.cellCollapser',{options:{togglerBtn:{showText:$t('View More'),hideText:$t('Hide'),className:'ambase-toggler-btn',template:'<button type="button" class="<%- className %>"><%- buttonText %></button>'},contentMaxHeight:'11rem',activeClassName:'-active',withCollapserClassName:'-with-collapser'},selectors:{collapsibleContent:'.ambase-collapsible-content'},isOpen:false,_create:function(){if(!this.hasOverflowContent()){return;}
this._addClass(this.options.withCollapserClassName);this.createTogglerButton();this._bind();},hasOverflowContent:function(){const collapsibleContent=this.getCollapsibleContent();return collapsibleContent.prop('clientHeight')<collapsibleContent.prop('scrollHeight');},createTogglerButton:function(){$(templateRenderer(this.options.togglerBtn.template,{buttonText:this.options.togglerBtn.showText,className:this.options.togglerBtn.className})).insertAfter(this.getCollapsibleContent())},_bind:function(){this._on({[`click .${this.options.togglerBtn.className}`]:this.toggle});},toggle:function(event){event.preventDefault();this.isOpen?this.hide():this.show();},show:function(){this.getTogglerBtn().text(this.options.togglerBtn.hideText);this._addClass(this.options.activeClassName);this.getCollapsibleContent().animate({maxHeight:this.getCollapsibleContent().prop('scrollHeight')},150);this.isOpen=true;},hide:function(){this.getTogglerBtn().text(this.options.togglerBtn.showText);this._removeClass(this.options.activeClassName);this.getCollapsibleContent().animate({maxHeight:this.options.contentMaxHeight},150);this.isOpen=false;},getTogglerBtn:function(){return $(this.element).find('.'+this.options.togglerBtn.className);},getCollapsibleContent:function(){return $(this.element).find(this.selectors.collapsibleContent);}});return $.ambase.cellCollapser;});